+        let want_prefixes: BTreeMap<Room, i64> = case
+            .get("final_prefixes")
+            .unwrap()
+            .as_obj()
+            .unwrap()
+            .iter()
+            .map(|(k, p)| (k.parse().unwrap(), p.as_int().unwrap()))
+            .collect();
+        assert_eq!(rooms.decode_prefix_lens, want_prefixes, "{name} prefixes");
